 230:   async recover(
 231:     organizationId: string,
 232:     executionId: string,
 233:     signal?: AbortSignal,
 234:   ): Promise<WorkflowExecution> {
 235:     const execution = this.executions.get(this.key(organizationId, executionId));
 236:     if (execution?.status !== 'RUNNING' && execution?.status !== 'FAILED')
 237:       throw new ValidationError('Workflow execution is not recoverable');
 238:     const workflow = this.require(organizationId, execution.workflowId);
 239:     const checkpoints =
 240:       this.store === undefined
 241:         ? this.listSteps(organizationId, executionId)
 242:         : await this.store.listSteps(organizationId, executionId);
 243:     const lastCompleted = [...checkpoints]
 244:       .filter((step) => step.status === 'COMPLETED')
 245:       .sort(
 246:         (left, right) =>
 247:           (right.completedAt?.getTime() ?? 0) - (left.completedAt?.getTime() ?? 0),
 248:       )[0];
 249:     return this.run(
 250:       execution,
 251:       workflow,
 252:       signal,
 253:       execution.currentNodeId,
 254:       lastCompleted === undefined ? execution.input : lastCompleted.output,
 255:     );
 256:   }
