 258:   async hydrate(execution: WorkflowExecution, workflow: Workflow): Promise<void> {
 259:     this.require(execution.organizationId, workflow.id);
 260:     if (this.executions.has(this.key(execution.organizationId, execution.id))) return;
 261:     this.executions.set(this.key(execution.organizationId, execution.id), execution);
 262:     if (execution.status !== 'WAITING_APPROVAL' || execution.approvalId === undefined) return;
 263:     const node = workflow.nodes.find((candidate) => candidate.id === execution.currentNodeId);
 264:     if (node?.kind !== 'Human Approval')
 265:       throw new ValidationError('Workflow approval node not found');
