 290:   private async run(
 291:     execution: WorkflowExecution,
 292:     workflow: Workflow,
 293:     signal?: AbortSignal,
 294:     startNodeId?: string,
 295:     initialValue: unknown = execution.input,
 296:   ): Promise<WorkflowExecution> {
 297:     let current = startNodeId ?? workflow.nodes[0]?.id;
 298:     let value = initialValue;
 299:     let currentExecution = execution;
 300:     let activeStep: WorkflowStepExecution | undefined;
 301:     try {
 302:       while (current !== undefined) {
 303:         if (signal?.aborted === true) throw new Error('Workflow execution cancelled');
 304:         const node = workflow.nodes.find((candidate) => candidate.id === current);
 305:         if (node === undefined) throw new ValidationError('Workflow node not found');
 306:         currentExecution = {
 307:           ...currentExecution,
 308:           status: 'RUNNING',
 309:           currentNodeId: node.id,
 310:           updatedAt: new Date(),
 311:         };
 312:         this.executions.set(this.key(execution.organizationId, execution.id), currentExecution);
 313:         await this.persistExecution(currentExecution);
 314:         const step: WorkflowStepExecution = {
 315:           id: uuidV7(),
 316:           tenantId: execution.organizationId,
 317:           organizationId: execution.organizationId,
 318:           executionId: execution.id,
 319:           nodeId: node.id,
 320:           status: 'RUNNING',
 321:           input: value,
 322:           version: 1,
 323:           startedAt: new Date(),
 324:           createdAt: new Date(),
 325:           updatedAt: new Date(),
 326:         };
 327:         activeStep = step;
 328:         this.steps.set(this.key(execution.organizationId, step.id), step);
 329:         await this.persistStep(step);
 330:         if (node.kind === 'Human Approval') {
 331:           const approval = await this.approvals.request({
 332:             id: uuidV7(),
 333:             organizationId: execution.organizationId,
 334:             requesterId: execution.principalId,
 335:             resource: `workflow:${workflow.id}`,
 336:             action: 'continue',
 337:             payloadDigest: execution.id,
 338:             requiredApprovers: asApprovers(node.config.approvers),
 339:           });
 340:           const waiting = {
 341:             ...currentExecution,
 342:             status: 'WAITING_APPROVAL' as const,
 343:             currentNodeId: node.id,
 344:             approvalId: approval.id,
 345:             updatedAt: new Date(),
 346:           };
 347:           this.executions.set(this.key(execution.organizationId, execution.id), waiting);
 348:           const waitingStep = {
 349:             ...step,
 350:             status: 'WAITING_APPROVAL' as const,
 351:             output: approval.id,
 352:             completedAt: new Date(),
 353:           };
 354:           activeStep = waitingStep;
 355:           this.steps.set(this.key(execution.organizationId, step.id), waitingStep);
 356:           await this.persistStep(waitingStep);
 357:           await this.persistExecution(waiting);
 358:           return waiting;
 359:         }
 360:         value = await this.executeNodeWithRetry(node, value, {
 361:           organizationId: execution.organizationId,
 362:           principalId: execution.principalId,
 363:           ...(signal === undefined ? {} : { signal }),
 364:         });
 365:         if (signal?.aborted === true) throw new Error('Workflow execution cancelled');
 366:         const completedStep = {
 367:           ...step,
 368:           status: 'COMPLETED' as const,
 369:           output: value,
 370:           completedAt: new Date(),
 371:         };
 372:         activeStep = completedStep;
 373:         this.steps.set(this.key(execution.organizationId, step.id), completedStep);
 374:         await this.persistStep(completedStep);
 375:         current = workflow.edges.find((edge) => edge.from === node.id)?.to;
 376:         currentExecution = {
 377:           ...currentExecution,
 378:           ...(current === undefined ? {} : { currentNodeId: current }),
 379:           updatedAt: new Date(),
 380:         };
 381:         this.executions.set(this.key(execution.organizationId, execution.id), currentExecution);
 382:         await this.persistExecution(currentExecution);
 383:       }
 384:       const completed = {
 385:         ...currentExecution,
 386:         status: 'COMPLETED' as const,
 387:         output: value,
 388:         updatedAt: new Date(),
 389:       };
 390:       this.executions.set(this.key(execution.organizationId, execution.id), completed);
 391:       await this.persistExecution(completed);
 392:       return completed;
 393:     } catch (error) {
 394:       const timedOut = error instanceof WorkflowTimeoutError && signal?.aborted !== true;
 395:       if (activeStep?.status === 'RUNNING') {
 396:         const failedStep = {
 397:           ...activeStep,
 398:           status: timedOut
 399:             ? ('TIMED_OUT' as const)
 400:             : signal?.aborted === true
 401:               ? ('CANCELLED' as const)
 402:               : ('FAILED' as const),
 403:           completedAt: new Date(),
 404:         };
 405:         this.steps.set(this.key(execution.organizationId, failedStep.id), failedStep);
 406:         await this.persistStep(failedStep);
 407:       }
 408:       const failed = {
 409:         ...currentExecution,
 410:         status: timedOut
 411:           ? ('TIMED_OUT' as const)
 412:           : signal?.aborted === true
 413:             ? ('CANCELLED' as const)
 414:             : ('FAILED' as const),
 415:         error:
 416:           timedOut
 417:             ? 'workflow_step_timeout'
 418:             : signal?.aborted === true
 419:             ? 'workflow_execution_cancelled'
 420:             : error instanceof Error
 421:               ? error.message
 422:               : String(error),
 423:         updatedAt: new Date(),
 424:       };
 425:       this.executions.set(this.key(execution.organizationId, execution.id), failed);
 426:       await this.persistExecution(failed);
 427:       return failed;
 428:     }
 429:   }
