 431:   private executeNodeWithTimeout(
 432:     node: WorkflowNode,
 433:     input: unknown,
 434:     context: { readonly organizationId: string; readonly principalId: string; readonly signal?: AbortSignal },
 435:   ): Promise<unknown> {
 436:     const timeout = timeoutMs(node);
 437:     if (timeout === undefined) return this.executeNode(node, input, context);
 438:     const controller = new AbortController();
 439:     const forwardAbort = () => controller.abort();
 440:     if (context.signal?.aborted === true) controller.abort();
 441:     else context.signal?.addEventListener('abort', forwardAbort, { once: true });
 442:     return new Promise((resolve, reject) => {
 443:       const timer = setTimeout(() => {
 444:         controller.abort();
 445:         reject(new WorkflowTimeoutError());
 446:       }, timeout);
 447:       void this.executeNode(node, input, { ...context, signal: controller.signal })
 448:         .then(resolve, reject)
 449:         .finally(() => {
 450:           clearTimeout(timer);
 451:           context.signal?.removeEventListener('abort', forwardAbort);
 452:         });
 453:     });
 454:   }
