 456:   private async executeNodeWithRetry(
 457:     node: WorkflowNode,
 458:     input: unknown,
 459:     context: { readonly organizationId: string; readonly principalId: string; readonly signal?: AbortSignal },
 460:   ): Promise<unknown> {
 461:     const policy = retryPolicy(node);
 462:     for (let attempt = 1; ; attempt += 1) {
 463:       try {
 464:         return await this.executeNodeWithTimeout(node, input, context);
 465:       } catch (error) {
 466:         if (attempt >= policy.maxAttempts || context.signal?.aborted === true) throw error;
 467:         if (policy.backoffMs > 0)
 468:           await new Promise<void>((resolve) => setTimeout(resolve, policy.backoffMs));
 469:         if (context.signal?.aborted === true) throw error;
 470:       }
 471:     }
 472:   }
