 494: function validateWorkflow(workflow: Workflow): void {
 495:   if (
 496:     workflow.id === '' ||
 497:     workflow.tenantId === '' ||
 498:     workflow.organizationId === '' ||
 499:     workflow.tenantId !== workflow.organizationId ||
 500:     workflow.nodes.length === 0
 501:   )
 502:     throw new ValidationError('Workflow organization and nodes are required');
 503:   const ids = new Set(workflow.nodes.map((node) => node.id));
 504:   if (
 505:     workflow.nodes.some((node) => node.id === '') ||
 506:     ids.size !== workflow.nodes.length ||
 507:     workflow.edges.some((edge) => !ids.has(edge.from) || !ids.has(edge.to))
 508:   )
 509:     throw new ValidationError('Workflow graph is invalid');
 510:   if (
 511:     workflow.nodes.some(
 512:       (node) => node.kind === 'Human Approval' && asApprovers(node.config.approvers).length === 0,
 513:     )
 514:   )
 515:     throw new ValidationError('Human Approval nodes require approvers');
 516:   for (const node of workflow.nodes) timeoutMs(node);
 517:   for (const node of workflow.nodes) retryPolicy(node);
 518: 
 519:   const outgoing = new Map<string, string[]>();
 520:   for (const node of workflow.nodes) outgoing.set(node.id, []);
 521:   for (const edge of workflow.edges) outgoing.get(edge.from)?.push(edge.to);
 522: 
 523:   const visiting = new Set<string>();
 524:   const visited = new Set<string>();
 525:   const visit = (nodeId: string): void => {
 526:     if (visiting.has(nodeId)) throw new ValidationError('Workflow graph contains a cycle');
 527:     if (visited.has(nodeId)) return;
 528:     visiting.add(nodeId);
 529:     for (const next of outgoing.get(nodeId) ?? []) visit(next);
 530:     visiting.delete(nodeId);
 531:     visited.add(nodeId);
 532:   };
 533:   for (const node of workflow.nodes) visit(node.id);
 534: }
