 543: function timeoutMs(node: WorkflowNode): number | undefined {
 544:   const value = node.config.timeoutMs;
 545:   if (value === undefined) return undefined;
 546:   if (typeof value !== 'number' || !Number.isInteger(value) || value <= 0 || value > 86_400_000)
 547:     throw new ValidationError('Workflow node timeoutMs must be an integer between 1 and 86400000');
 548:   return value;
 549: }
 550: 
 551: interface WorkflowRetryPolicy {
 552:   readonly maxAttempts: number;
 553:   readonly backoffMs: number;
 554: }
 555: 
 556: function retryPolicy(node: WorkflowNode): WorkflowRetryPolicy {
 557:   const value = node.config.retry;
 558:   if (value === undefined) return { maxAttempts: 1, backoffMs: 0 };
 559:   if (typeof value !== 'object' || value === null || Array.isArray(value))
 560:     throw new ValidationError('Workflow node retry must be an object');
 561:   const candidate = value as { readonly maxAttempts?: unknown; readonly backoffMs?: unknown };
 562:   const maxAttempts = candidate.maxAttempts ?? 1;
 563:   const backoffMs = candidate.backoffMs ?? 0;
 564:   if (
 565:     typeof maxAttempts !== 'number' ||
 566:     !Number.isInteger(maxAttempts) ||
 567:     maxAttempts < 1 ||
 568:     maxAttempts > 10 ||
 569:     typeof backoffMs !== 'number' ||
 570:     !Number.isInteger(backoffMs) ||
 571:     backoffMs < 0 ||
 572:     backoffMs > 60_000
 573:   )
 574:     throw new ValidationError('Workflow node retry must use maxAttempts 1-10 and backoffMs 0-60000');
 575:   return { maxAttempts, backoffMs };
 576: }
